pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to deposit, and attacker address (as an address to receive funds / act)
    function testFuzz_property(uint256 amt, address attackerAddr) public {
        // keep amounts reasonable and non-zero to exercise withdraw path
        amt = bound(amt, 1, 1 ether);
        vm.assume(attackerAddr != address(0));

        // deploy an adversarial reentrant helper that will re-enter withdrawAll during receive
        Attacker attacker = new Attacker(c);
        address attackerContract = address(attacker);

        // fund the attacker externally so it can deposit
        vm.deal(attackerContract, amt);

        // attacker deposits into c
        vm.prank(attackerContract);
        c.deposit{value: amt}();

        // sanity: contract balance increased
        // now perform withdrawAll from attacker; attacker will try to re-enter during the external call
        vm.prank(attackerContract);
        // call withdrawAll; the reference implementation zeroes credit before the external call
        // while the mutant makes the external call first, enabling reentrancy to withdraw twice
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // one universal property: after withdrawAll completes, the stored credit for the caller must be zero
        // read credit by calling the auto-generated getter (credit is private in original, but per problem it's mapping(address=>uint) credit; assuming public getter exists — if not, we can observe via address(c).balance vs expected; but requirement mandates using public surface. Here we assume credit is public.)
        // The specification requires exactly one assertTrue call that reads c. We'll check that the credit of attackerContract is zero.

        // Try to read credit via low-level call to auto-generated getter; if getter doesn't exist this will revert — but problem statement allows reading public getters only.
        // Use try/catch around a call to c.withdrawAll would be for revert differences; here we assert credit == 0 via calling the public getter credit(address)

        // Build calldata for credit getter: credit(address) -> uint256
        (bool got, bytes memory data) = address(c).call(abi.encodeWithSignature("credit(address)", attackerContract));
        uint256 stored = 0;
        if (got && data.length >= 32) {
            stored = abi.decode(data, (uint256));
        }

        assertTrue(stored == 0);
    }
}

// Minimal attacker that re-enters withdrawAll during receive
contract Attacker {
    C public target;
    bool public reentered;
    constructor(C _t) {
        target = _t;
        reentered = false;
    }
    // receive will be called when target calls msg.sender.call{value: ...}()
    receive() external payable {
        // attempt reentrancy only once
        if (!reentered) {
            reentered = true;
            // re-enter withdrawAll to attempt to drain again if target hasn't zeroed credit
            (bool success, ) = address(target).call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success
            success;
        }
    }
}

