pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositAmount (must be >0) and attacker initialBalance (to fund reentrancy)
    function testFuzz_property(uint256 depositAmount, uint256 attackerBalance) public {
        // keep domains wide but meaningful
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerBalance = bound(attackerBalance, 1, 1 ether);

        // deploy attacker that re-enters on receive
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can deposit and receive callbacks
        vm.deal(address(attacker), attackerBalance);

        // attacker deposits depositAmount into c
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // record totalStoredCredits as the contract balance before withdraw
        uint256 beforeStored = address(c).balance;

        // attacker will call withdrawAll which in mutant may allow reentrancy to change invariants
        vm.prank(address(attacker));
        // perform withdrawAll via attacker to trigger its receive fallback during the external call
        attacker.callWithdrawAll();

        // Single assertion: after withdrawAll completes, contract balance must equal sum of stored credits.
        // We can only read address(c).balance; in the reference, balance tracks credits, so address(c).balance == beforeStored - withdrawn.
        // Using the attacker that re-enters can cause mismatch under mutant; the correct contract always preserves consistency
        assertTrue(address(c).balance <= beforeStored);
    }
}

// Minimal attacker that re-enters by calling deposit again during receive, to exploit if external call happens before zeroing.
contract Attacker {
    address payable public target;
    bool public reentered;

    constructor(address _target) payable {
        target = payable(_target);
    }

    // called by test to invoke withdrawAll on target
    function callWithdrawAll() external {
        C(target).withdrawAll();
    }

    // receive will try to re-enter: deposit a small amount back to the contract to disturb balances
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter by calling withdrawAll on target (if vulnerable, this will run during external call)
            // first deposit a tiny amount so credit mapping changes
            C(target).deposit{value: 1}();
            // then attempt withdraw again to trigger reentrancy effect
            // note: using low-level call is not necessary; direct call to withdrawAll suffices
            C(target).withdrawAll();
        }
    }
}

