pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and an amount > 0
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero and amount in a reasonable gas-affordable bound and positive
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund the actor and perform deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // sanity: after deposit, the contract balance should be at least amount
        // now actor withdraws all
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if withdrawAll completed successfully, the recorded credit for actor becomes zero
        // We assert that for the reference contract this holds for all inputs; the mutant that does not reset
        // credit will leave credit > 0 for some inputs, making this assertion fail.
        if (ok) {
            // single assertion reading c's public surface: credit mapping is public? It's not public in original, but we can
            // observe via trying another withdrawAll: in reference, second withdrawAll should be a no-op (no ether sent),
            // and the contract balance should not change further. However tests must read c only via public interface.
            // The contract has no getter for credit; but we can observe that after first successful withdrawAll,
            // calling withdrawAll again will produce ok2 = true but not transfer any funds (no revert). The distinguishing
            // observable is address(c).balance: in reference it decreased by amount once; in mutant it decreased again
            // if attacker receives again (actually mutant leaves credit so repeated calls re-send). So we perform a second
            // withdrawAll and assert that address(c).balance did not change after the second call.

            uint256 balBefore = address(c).balance;
            vm.prank(actor);
            // perform second withdrawAll; catch revert just in case
            bool ok2;
            try c.withdrawAll() {
                ok2 = true;
            } catch {
                ok2 = false;
            }
            uint256 balAfter = address(c).balance;

            // The reference: second call should not reduce contract balance further, so balAfter == balBefore.
            assertTrue(balAfter == balBefore);
        } else {
            // if initial withdraw reverted, we cannot assert the in-variant about zeroing; just pass by asserting true
            assertTrue(true);
        }
    }
}

